// Everything but `pack` is optional. The audio is mono 16-bit PCM at the pack's sample rate
// (no resampling: another rate is `E0319`), pushed as raw samples or as a WAV file whose header
// comes first. A pass is an `audio` run of the pack on the newest `window_seconds` of the
// utterance, so what a pass says is what the same samples would say offline.
type StreamOpen struct {
	// The speech pack.
	Pack string `json:"pack"`
	// What the pushed bytes are: `pcm16` (raw little-endian samples, the default) or `wav` (a
	// header, then the samples; a data size of 0 or 0xFFFFFFFF in the header means until the
	// pushes end, any other size is honoured and the bytes after it are ignored).
	Format *AudioFormat `json:"format,omitempty"`
	// The rate of raw `pcm16` samples; the pack's when absent. For `wav` the header says, and a
	// value here must agree with it.
	SampleRate *uint32 `json:"sample_rate,omitempty"`
	// Force the spoken language, as for an `audio` input.
	Language *string `json:"language,omitempty"`
	// Text given to the decoder after the audio of every pass.
	Prompt *string `json:"prompt,omitempty"`
	// Text given to the decoder before the audio of every pass.
	PromptBefore *string `json:"prompt_before,omitempty"`
	// Output options of every pass: `keywords`, `keyword_boost`, `max_tokens`, `stop`. A schema,
	// `tool_choice` or `logprobs` is refused (`E0315`).
	Output *OutputOptions `json:"output,omitempty"`
	// The longest stretch of audio one pass decodes, in seconds: 1 up to the pack's pass
	// (`latai.audio.max_seconds`, at most 30, which is also the default). The session never holds
	// more than this plus one chunk and the pre-roll.
	WindowSeconds *uint32 `json:"window_seconds,omitempty"`
	// Milliseconds of new audio between two passes of an utterance: [`HOP_MS_MIN`] to half the
	// window (default [`HOP_MS_DEFAULT`], at most half the window). A shorter hop shows words
	// sooner and costs more passes; it is at most half the window so that every word is seen by
	// two passes while it is inside the window. `0`: no pass until the window is full, then every
	// half window, so an utterance that fits one window is decoded once, at its end, exactly as
	// the same samples are offline (and one that does not fit loses nothing).
	HopMS *uint32 `json:"hop_ms,omitempty"`
	// Milliseconds of silence that end an utterance ([`PAUSE_MS_MIN`] to [`PAUSE_MS_MAX`],
	// default [`PAUSE_MS_DEFAULT`]); `0` turns endpointing off, so the stream is one utterance
	// from its first sample (its committed text then equals the offline transcript of the same
	// audio when it fits one window).
	PauseMS *uint32 `json:"pause_ms,omitempty"`
	// The loudest sample (of 32768) that still counts as silence for the voice check, 0 to
	// 1,024; the pack's `latai.audio.silence_peak` (16 by default) when absent.
	SilencePeak *uint32 `json:"silence_peak,omitempty"`
	// End the stream (`E0312 stream_seconds`) after this many seconds of audio; at most
	// [`STREAM_MAX_SECONDS`], which is also the default.
	MaxSeconds *uint32 `json:"max_seconds,omitempty"`
	// The time the whole stream may take from its open, in milliseconds; when it passes the stream
	// ends with `E0702`. Each pass gets what is left. None: no deadline.
	DeadlineMS *uint64 `json:"deadline_ms,omitempty"`
	// Refuse the stream unless the pack's digest is this.
	ExpectDigest *string `json:"expect_digest,omitempty"`
	// Run this second stage on every utterance's committed text when the utterance ends (12.2.3).
	Then *Then `json:"then,omitempty"`
}

// One item of a stream session; the `event` field picks the kind. See the module docs for the
// rules every sequence follows.
// Exactly one field is set; Unknown holds a variant this SDK does not know (its whole JSON).
type StreamEvent struct {
	Partial   *StreamEventPartial
	Committed *StreamEventCommitted
	Utterance *StreamEventUtterance
	Then      *StreamEventThen
	Final     *StreamEventFinal
	Error     *StreamEventError
	Unknown   json.RawMessage
}

// The uncommitted words so far, replacing the previous `partial`. May be revised.
type StreamEventPartial struct {
	// The utterance (counted from 0) the words belong to.
	Utterance uint64 `json:"utterance"`
	Text      string `json:"text"`
	// The end of the pass that heard it, in milliseconds of audio from the stream's start.
	AtMS uint64 `json:"at_ms"`
}

// New committed words. Never revised, never repeated.
type StreamEventCommitted struct {
	Utterance uint64 `json:"utterance"`
	Text      string `json:"text"`
	AtMS      uint64 `json:"at_ms"`
}

// An utterance ended; `text` is everything committed in it.
type StreamEventUtterance struct {
	Utterance uint64 `json:"utterance"`
	Text      string `json:"text"`
	StartMS   uint64 `json:"start_ms"`
	EndMS     uint64 `json:"end_ms"`
	// The sample range `[start_sample, end_sample)` of the stream the last pass decoded
	// (or, for a long utterance, the end of it), so a client can run the same samples offline.
	StartSample uint64 `json:"start_sample"`
	EndSample   uint64 `json:"end_sample"`
}

// The second stage ran on the text of an utterance (12.2.3). `response` is the second
// stage's response, as a run of that pack on `text` by hand gives it.
type StreamEventThen struct {
	Utterance uint64   `json:"utterance"`
	Text      string   `json:"text"`
	Response  Response `json:"response"`
}

// The stream ended. The one terminal event of a stream that opened.
type StreamEventFinal struct {
	Response Response `json:"response"`
}

// The stream could not open. The one terminal event of a stream that never ran.
type StreamEventError struct {
	Error WireError `json:"error"`
}

// MarshalJSON writes the set variant with its "event" tag.
func (u StreamEvent) MarshalJSON() ([]byte, error) {
	switch {
	case u.Partial != nil:
		return tagged("event", "partial", u.Partial)
	case u.Committed != nil:
		return tagged("event", "committed", u.Committed)
	case u.Utterance != nil:
		return tagged("event", "utterance", u.Utterance)
	case u.Then != nil:
		return tagged("event", "then", u.Then)
	case u.Final != nil:
		return tagged("event", "final", u.Final)
	case u.Error != nil:
		return tagged("event", "error", u.Error)
	case u.Unknown != nil:
		return u.Unknown, nil
	}
	return nil, fmt.Errorf("latai: StreamEvent has no variant set")
}

// UnmarshalJSON reads the "event" tag and fills the one variant it names.
func (u *StreamEvent) UnmarshalJSON(data []byte) error {
	tag, err := tagOf(data, "event")
	if err != nil {
		return err
	}
	*u = StreamEvent{}
	switch tag {
	case "partial":
		u.Partial = new(StreamEventPartial)
		return json.Unmarshal(data, u.Partial)
	case "committed":
		u.Committed = new(StreamEventCommitted)
		return json.Unmarshal(data, u.Committed)
	case "utterance":
		u.Utterance = new(StreamEventUtterance)
		return json.Unmarshal(data, u.Utterance)
	case "then":
		u.Then = new(StreamEventThen)
		return json.Unmarshal(data, u.Then)
	case "final":
		u.Final = new(StreamEventFinal)
		return json.Unmarshal(data, u.Final)
	case "error":
		u.Error = new(StreamEventError)
		return json.Unmarshal(data, u.Error)
	}
	u.Unknown = append(json.RawMessage(nil), data...)
	return nil
}

